import{_ as a,o as r,c as t,a3 as n}from"./chunks/framework.C6R8kWFE.js";const g=JSON.parse('{"title":"衡益","description":"","frontmatter":{"title":"衡益","sidebar":false},"headers":[],"relativePath":"members/faculty/heng-yi.md","filePath":"members/faculty/heng-yi.md"}'),s={name:"members/faculty/heng-yi.md"};function o(i,e,l,c,h,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="衡益" tabindex="-1">衡益 <a class="header-anchor" href="#衡益" aria-label="Permalink to &quot;衡益&quot;">​</a></h1><p><strong>职称：</strong> 教授、博士生导师（计算数学与计算机科学与技术双专业）</p><p><strong>单位：</strong> <a href="https://cse.sysu.edu.cn/" target="_blank" rel="noreferrer">中山大学计算机学院</a> · 广东省计算科学重点实验室副主任</p><p><strong>联系邮箱：</strong> <a href="mailto:hengyi@mail.sysu.edu.cn" target="_blank" rel="noreferrer">hengyi@mail.sysu.edu.cn</a></p><p><strong>联系地址：</strong> 广州市番禺区大学城外环东路132号</p><p><strong>学院主页：</strong> <a href="https://cse.sysu.edu.cn/teacher/HengYi" target="_blank" rel="noreferrer">中山大学计算机学院 — 衡益</a></p><h2 id="个人简介" tabindex="-1">个人简介 <a class="header-anchor" href="#个人简介" aria-label="Permalink to &quot;个人简介&quot;">​</a></h2><p>国家重大人才计划青年专家、广东省重大人才工程青年拔尖人才。研究方向紧密围绕 <strong>「HPC + AI for Science and Engineering」</strong>，聚焦数学物理反问题、高性能科学计算与人工智能的交叉融合，推动多学科协同创新与工程应用。</p><p>曾在德国亚琛工业大学获自然科学博士学位，并曾任职于德国于利希国家实验室等国际研究机构。回国后主持及参与国家级、省部级及企业合作项目多项，自主研发高性能多物理场仿真智能工业软件 <strong>FIND Multiphysics</strong>（获广东省工业软件科学技术发明一等奖），在《The Innovation》《Science Bulletin》《Environmental Science &amp; Technology》《Water Research》《Inverse Problems》等期刊发表学术论文 70 余篇。</p><h2 id="研究方向" tabindex="-1">研究方向 <a class="header-anchor" href="#研究方向" aria-label="Permalink to &quot;研究方向&quot;">​</a></h2><ol><li>偏微分方程数学物理正反问题与高性能科学计算</li><li>多物理场耦合仿真工业软件与智慧工业数字孪生</li><li>仿真智能、工业大模型与 AI Agent 智能体技术</li><li>典型应用：极端环境多学科联合仿真、AI 驱动的绿色低碳水处理、工业数智化操作、生物医药智能发现与合成推荐、高端新材料智能优化设计等</li></ol><h2 id="招生信息" tabindex="-1">招生信息 <a class="header-anchor" href="#招生信息" aria-label="Permalink to &quot;招生信息&quot;">​</a></h2><p>课题组面向全球招收博士研究生、硕士研究生及本科生科研助手，欢迎数学、计算机、力学、物理、化学与化工、机械工程、材料工程等相关专业背景的同学联系。具体名额与条件请通过邮件咨询。</p><p><a href="/members/">← 返回课题组成员</a></p>',14)])])}const m=a(s,[["render",o]]);export{g as __pageData,m as default};
